/**
 * The third-party licences blurrd ships, as generated by
 * `scripts/licenses.mjs` into `licenses.json` (schema `blurrd-licenses/1`).
 * The data is about 600 kB, so it is loaded on demand as its own chunk.
 */

/** What a component is. */
export type ComponentKind = "binary" | "model" | "crate" | "npm";

/** One shipped third-party component. */
export interface LicensedComponent {
  readonly kind: ComponentKind;
  readonly name: string;
  readonly version: string;
  /** The licence as the component declares it (an SPDX expression or a name). */
  readonly license: string;
  /** Project or package page. */
  readonly url: string;
  /** Where the corresponding source code is published (FFmpeg). */
  readonly source?: string;
  /** How blurrd uses or obtained the component. */
  readonly note?: string;
  /** Indexes into {@link LicenseData.texts}. */
  readonly texts: readonly number[];
}

/** One licence text, shared by every component that ships it. */
export interface LicenseText {
  /** Short name of the licence. */
  readonly license: string;
  readonly text: string;
}

/** The generated licence data. */
export interface LicenseData {
  readonly schema: typeof LICENSE_SCHEMA;
  readonly packages: readonly LicensedComponent[];
  readonly texts: readonly LicenseText[];
}

/** Format tag the generator writes. */
export const LICENSE_SCHEMA = "blurrd-licenses/1";

/** Section titles per kind, in display order. */
export const KIND_TITLES: Readonly<Record<ComponentKind, string>> = {
  binary: "Bundled programs",
  model: "OCR models",
  crate: "Rust crates",
  npm: "npm packages",
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function isComponent(value: unknown, textCount: number): value is LicensedComponent {
  return (
    isRecord(value) &&
    typeof value.kind === "string" &&
    value.kind in KIND_TITLES &&
    typeof value.name === "string" &&
    typeof value.version === "string" &&
    typeof value.license === "string" &&
    typeof value.url === "string" &&
    Array.isArray(value.texts) &&
    value.texts.every(
      (index) => Number.isInteger(index) && Number(index) >= 0 && Number(index) < textCount,
    )
  );
}

/** Checks the shape of parsed licence data. */
export function parseLicenseData(value: unknown): LicenseData {
  if (!isRecord(value) || value.schema !== LICENSE_SCHEMA) {
    throw new Error(`the licence data is not ${LICENSE_SCHEMA}`);
  }
  const { packages, texts } = value;
  if (
    !Array.isArray(texts) ||
    !texts.every(
      (entry) =>
        isRecord(entry) && typeof entry.license === "string" && typeof entry.text === "string",
    ) ||
    !Array.isArray(packages) ||
    !packages.every((entry) => isComponent(entry, texts.length))
  ) {
    throw new Error("the licence data is malformed");
  }
  return { schema: LICENSE_SCHEMA, packages, texts };
}

/** Loads the generated licence data (a separate chunk, read once). */
export async function loadLicenses(): Promise<LicenseData> {
  const { default: raw } = await import("./licenses.json?raw");
  return parseLicenseData(JSON.parse(raw));
}

/**
 * Components whose name, version or licence contains every word of
 * `query` (case-insensitive), in their original order.
 */
export function filterComponents(
  packages: readonly LicensedComponent[],
  query: string,
): readonly LicensedComponent[] {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (words.length === 0) return packages;
  return packages.filter((item) => {
    const haystack = `${item.name} ${item.version} ${item.license}`.toLowerCase();
    return words.every((word) => haystack.includes(word));
  });
}

/** Where the source code of the shipped FFmpeg build is published, if listed. */
export function ffmpegSource(data: LicenseData): string | null {
  return data.packages.find((item) => item.kind === "binary" && item.source)?.source ?? null;
}
